def roman_to_int(s):
    if not s or any(c.lower() not in 'ivxlcdm' for c in s):
        return None

    mapping = {
        'i': 1, 'v': 5, 'x': 10, 'l': 50,
        'c': 100, 'd': 500, 'm': 1000
    }

    result = 0
    prev_value = 0

    for char in reversed(s):
        value = mapping[char]
        if value < prev_value:
            result -= value
        else:
            result += value
        prev_value = value

    return result
```

