def luhn_valid(s):
    s = ''.join(filter(str.isdigit, s)).strip()
    if len(s) < 2:
        return False

    def digit_sum(n):
        return sum(int(digit) for digit in str(n))

    total = 0
    for i in range(len(s)):
        digit = int(s[-(i+1)])
        if i % 2 == 0:
            total += digit
        else:
            total += digit_sum(2 * digit)

    return total % 10 == 0
```

