def camel_to_snake(s):
    result = ""
    capitalize_next = False
    for char in s:
        if char.isupper() and not capitalize_next:
            result += "_" + char.lower()
            capitalize_next = True
        elif char.isdigit():
            result += char
        else:
            result += char.lower()
            capitalize_next = False
    return result
```

