def parse_duration(s):
    parts = s.split(':')
    if len(parts) == 1:
        try:
            return int(parts[0])
        except ValueError:
            return None
    elif len(parts) == 2:
        hours, minutes = map(int, parts)
        return hours * 3600 + minutes * 60
    elif len(parts) == 3:
        hours, minutes, seconds = map(int, parts)
        return hours * 3600 + minutes * 60 + seconds
    else:
        return None
